/* ---------- 敦煌/酒泉再补充 ---------- */
{"name":"西千佛洞","label":"西千佛洞","region":"甘肃省","city":"酒泉市","county":"敦煌市","theme":"石窟艺术","elev":1150,"best":"全年","lat":40.02,"lng":94.6,"desc":"莫高窟以西35公里的姊妹石窟，开凿于党河崖壁，现存北魏至隋唐洞窟十余座。窟内壁画彩塑精美，与莫高窟同源同脉，是敦煌石窟艺术的重要组成部分。","wiki":"西千佛洞","img":"images_gs/s269.svg"},
{"name":"莫高窟数字展示中心","label":"莫高窟数字展示中心","region":"甘肃省","city":"酒泉市","county":"敦煌市","theme":"城市地标","elev":1200,"best":"全年","lat":40.04,"lng":94.79,"desc":"球幕影院与数字展厅相结合，以4K超高清呈现莫高窟精华洞窟，《千年莫高》《梦幻佛宫》震撼上映。是游莫高窟前的数字导览，科技让千年壁画永续传世。","wiki":"","img":"images_gs/s270.svg"},
{"name":"敦煌玄奘博物馆","label":"玄奘取经博物馆","region":"甘肃省","city":"酒泉市","county":"敦煌市","theme":"城市地标","elev":1200,"best":"全年（周一闭馆）","lat":40.08,"lng":94.75,"desc":"以玄奘西行求法为主题的专题博物馆，再现玄奘经敦煌出关的取经之路。馆藏壁画复制品与经卷，讲述大唐西域记里的丝路故事，是敦煌丝路文化的重要补充。","wiki":"","img":"images_gs/s271.svg"},
{"name":"敦煌月牙泉小镇","label":"月牙泉小镇","region":"甘肃省","city":"酒泉市","county":"敦煌市","theme":"民族风情","elev":1200,"best":"全年","lat":40.08,"lng":94.72,"desc":"鸣沙山下的丝路风情小镇，仿唐建筑街巷与民俗演艺相映。驼队、胡杨与飞天元素装点街市，敦煌美食与手作在此汇聚，是游完鸣沙山的休闲去处。","wiki":"","img":"images_gs/s272.svg"},
{"name":"敦煌胡杨林","label":"敦煌胡杨林","region":"甘肃省","city":"酒泉市","county":"敦煌市","theme":"森林山川","elev":1100,"best":"9月下旬-10月中旬","lat":40.1,"lng":94.5,"desc":"大漠深处的金色胡杨，秋季胡杨林一片金黄，与沙丘湿地相映。胡杨千年不倒的倔强生命力，在敦煌戈壁中尤为动人，是敦煌秋季的摄影秘境。","wiki":"","img":"images_gs/s273.svg"},
/* ---------- 嘉峪关再补充 ---------- */
{"name":"嘉峪关黑山岩画","label":"黑山岩画","region":"甘肃省","city":"嘉峪关市","county":"","theme":"古城遗址","elev":1700,"best":"全年","lat":39.88,"lng":98.1,"desc":"黑山峡谷中的远古岩画，摩崖石刻展现先民狩猎、舞蹈与牧羊场景，距今数千年，有西北原始艺术画廊之誉。岩画与黑山戈壁相映，是嘉峪关最古老的文化遗存。","wiki":"黑山岩画","img":"images_gs/s274.svg"},
/* ---------- 武威再补充 ---------- */
{"name":"天祝石门沟","label":"石门沟草原","region":"甘肃省","city":"武威市","county":"天祝县","theme":"草原湿地","elev":2900,"best":"6-9月","lat":37.05,"lng":102.85,"desc":"抓喜秀龙草原深处的高山牧场，草甸起伏、溪流清澈，藏式帐篷与牛羊相映。草原与雪山松林相接，是天祝夏季避暑露营的秘境牧场。","wiki":"","img":"images_gs/s275.svg"},
{"name":"民勤青土湖","label":"青土湖","region":"甘肃省","city":"武威市","county":"民勤县","theme":"草原湿地","elev":1350,"best":"全年（候鸟季）","lat":38.9,"lng":103.7,"desc":"石羊河尾闾的生态湖泊，一度干涸的湖面经生态治理重现碧波，被誉为民勤治沙的绿色奇迹。湖水与芦苇、沙丘相映，候鸟归来，是河西生态复苏的见证。","wiki":"青土湖","img":"images_gs/s276.svg"},
{"name":"天祝松山古城","label":"松山古城","region":"甘肃省","city":"武威市","county":"天祝县","theme":"古城遗址","elev":2800,"best":"全年","lat":37.2,"lng":103.3,"desc":"明代松山古城遗址，为防御蒙古而筑的军事边城，城墙夯土保存完好。古城雄踞松山草原，与雪山牧场相映，是河西走廊明代边防的实证。","wiki":"松山古城","img":"images_gs/s277.svg"},
{"name":"武威天马湖","label":"天马湖","region":"甘肃省","city":"武威市","county":"凉州区","theme":"城市地标","elev":1500,"best":"全年（夜景）","lat":37.93,"lng":102.66,"desc":"武威城区的人工湖，以马踏飞燕（铜奔马）文化命名，湖面开阔、绿道环湖。夜晚灯光倒映湖面，天马雕塑与城市灯火相映，是凉州的城市水景地标。","wiki":"","img":"images_gs/s278.svg"},
/* ---------- 张掖再补充 ---------- */
{"name":"张掖万寿寺木塔","label":"甘州木塔","region":"甘肃省","city":"张掖市","county":"甘州区","theme":"宗教圣地","elev":1470,"best":"全年","lat":38.93,"lng":100.45,"desc":"甘州八景之一的万寿寺木塔，始建于北周，木结构塔身历经千年，登塔可眺张掖古城。木塔与钟鼓楼相望，是张掖历史最悠久的古建地标。","wiki":"万寿寺木塔","img":"images_gs/s279.svg"},
{"name":"山丹峡口古城","label":"峡口古城","region":"甘肃省","city":"张掖市","county":"山丹县","theme":"长城关隘","elev":1800,"best":"全年","lat":38.6,"lng":101.2,"desc":"汉明长城旁的屯兵古城，峡口古城扼守长城要道，石城与烽燧保存完好。古城残墙、驿道与长城相映，是河西走廊明长城防御体系的实证。","wiki":"峡口古城","img":"images_gs/s280.svg"},
{"name":"肃南文殊山石窟","label":"文殊山石窟","region":"甘肃省","city":"张掖市","county":"肃南县","theme":"石窟艺术","elev":1800,"best":"全年","lat":39.3,"lng":99.3,"desc":"河西走廊重要的早期石窟群，北凉始建，现存洞窟与壁画保存较好，与马蹄寺、天梯山同为凉州石窟系统。石窟依文殊山而建，是研究佛教东渐的关键遗存。","wiki":"文殊山石窟","img":"images_gs/s281.svg"},
/* ---------- 甘南再补充 ---------- */
{"name":"迭部骨麻湖","label":"骨麻湖","region":"甘肃省","city":"甘南州","county":"迭部县","theme":"草原湿地","elev":3800,"best":"6-9月","lat":34.2,"lng":103.1,"desc":"迭部深山的高山圣湖，湖水幽蓝、雪山倒映，湖畔草甸野花遍地，藏民视其为神湖。湖区人迹罕至、静谧纯净，是甘南最隐秘的高原湖泊秘境。","wiki":"","img":"images_gs/s282.svg"},
{"name":"卓尼九甸峡","label":"九甸峡","region":"甘肃省","city":"甘南州","county":"卓尼县","theme":"峡谷天堑","elev":2300,"best":"全年","lat":34.75,"lng":103.6,"desc":"洮河切穿山峦的峡谷，两岸绝壁对峙、水势湍急，古为洮河天险。九甸峡水库高峡平湖，峡谷与碧水相映，是卓尼东部壮美的山水奇观。","wiki":"九甸峡","img":"images_gs/s283.svg"},
{"name":"舟曲拉尕山","label":"拉尕山","region":"甘肃省","city":"甘南州","county":"舟曲县","theme":"森林山川","elev":2850,"best":"5-10月","lat":33.9,"lng":104.1,"desc":"白龙江畔的名山，藏语意为神仙居住的地方，山峰俊秀、森林葱郁，寺庙与村落点缀其间。山间云海与田园相映，是舟曲山水风光的代表。","wiki":"拉尕山","img":"images_gs/s284.svg"},
{"name":"迭部白龙江峡谷","label":"白龙江峡谷","region":"甘肃省","city":"甘南州","county":"迭部县","theme":"江河峡谷","elev":2400,"best":"全年","lat":34.05,"lng":103.15,"desc":"白龙江穿行迭部山间的峡谷，江水碧绿、两岸青山如屏，藏寨与农田沿江散布。峡谷风光秀丽，是迭部扎尕那之外的山水画廊。","wiki":"","img":"images_gs/s285.svg"},
/* ---------- 临夏再补充 ---------- */
{"name":"积石山保安三庄","label":"保安三庄","region":"甘肃省","city":"临夏州","county":"积石山县","theme":"民族风情","elev":2200,"best":"全年","lat":35.8,"lng":102.8,"desc":"保安族的主要聚居村落，大墩、梅坡、甘河滩三庄依山傍水。保安腰刀锻制技艺闻名天下，村落保留保安族传统生活，是体验保安族文化的活态村庄。","wiki":"保安族","img":"images_gs/s286.svg"},
/* ---------- 白银再补充 ---------- */
{"name":"白银黄河大峡","label":"黄河大峡","region":"甘肃省","city":"白银市","county":"白银区","theme":"江河峡谷","elev":1400,"best":"全年","lat":36.4,"lng":104.2,"desc":"黄河切穿白银的峡谷段，峡谷两岸峰峦叠嶂，河水奔流，有白银小三峡之誉。乘船游峡可观奇峰与河湾，是白银山水风光的代表。","wiki":"","img":"images_gs/s287.svg"},
{"name":"平川屈吴山","label":"屈吴山","region":"甘肃省","city":"白银市","county":"平川区","theme":"森林山川","elev":2400,"best":"5-10月","lat":36.5,"lng":104.8,"desc":"平川境内的名山，相传老子讲经之地，山上寺庙道观香火千年。林木葱郁、云海翻涌，登顶可览黄河川塬，是白银道教文化与自然风光结合的名山。","wiki":"屈吴山","img":"images_gs/s288.svg"},
/* ---------- 定西再补充 ---------- */
{"name":"临洮岳麓山","label":"岳麓山","region":"甘肃省","city":"定西市","county":"临洮县","theme":"森林山川","elev":2200,"best":"全年","lat":35.37,"lng":103.86,"desc":"临洮城东的名山，山上存唐代哥舒翰纪功碑与岳麓书院遗址，有陇上文化名山之誉。山势秀美、亭台错落，登顶可眺洮河与县城，是临洮人文山水的代表。","wiki":"岳麓山","img":"images_gs/s289.svg"},
{"name":"岷县二郎山","label":"二郎山","region":"甘肃省","city":"定西市","county":"岷县","theme":"红色遗迹","elev":2400,"best":"全年","lat":34.43,"lng":104.02,"desc":"岷县城外的红色名山，1936年红军长征在此激战二郎山，岷州会议旧址近在咫尺。山上红军战斗遗址与纪念碑保存完好，登顶可瞰岷州古城，是岷县红色旅游的核心。","wiki":"二郎山","img":"images_gs/s290.svg"},
/* ---------- 庆阳再补充 ---------- */
{"name":"华池大凤川","label":"大凤川林区","region":"甘肃省","city":"庆阳市","county":"华池县","theme":"森林山川","elev":1500,"best":"5-10月","lat":36.4,"lng":108.2,"desc":"子午岭林区的森林峡谷，原始森林茂密、溪流淙淙，抗日战争时期八路军大生产运动在此开荒。林海与红色记忆相映，是华池生态与历史交融的宝地。","wiki":"","img":"images_gs/s291.svg"},
/* ---------- 酒泉肃州再补充 ---------- */
{"name":"肃州花城湖","label":"花城湖","region":"甘肃省","city":"酒泉市","county":"肃州区","theme":"草原湿地","elev":1400,"best":"全年","lat":39.9,"lng":98.6,"desc":"肃州城北的湿地湖泊，湖水澄澈、芦苇摇曳，水鸟栖息，有酒泉湿地明珠之誉。环湖栈道与花田相映，是酒泉人近郊亲水的生态绿洲。","wiki":"","img":"images_gs/s292.svg"},
/* ---------- 收尾补充 ---------- */
{"name":"敦煌光电产业园","label":"敦煌光电产业园","region":"甘肃省","city":"酒泉市","county":"敦煌市","theme":"城市地标","elev":1200,"best":"全年（日落尤佳）","lat":40.1,"lng":94.5,"desc":"亚洲最大熔盐塔式光热电站，上万面定日镜环绕高塔，如银色向日葵阵列戈壁。傍晚夕阳下镜阵熠熠生辉，是敦煌科技与荒原交融的壮观地标。","wiki":"敦煌光热电站","img":"images_gs/s293.svg"},
{"name":"张家川关山草原","label":"关山草原","region":"甘肃省","city":"天水市","county":"张家川县","theme":"草原湿地","elev":2400,"best":"6-9月","lat":34.9,"lng":106.3,"desc":"陕甘交界的关山牧场，草甸起伏如绿毯、森林与山峦相映，有陇上阿尔卑斯之誉。夏季牧群如云、凉风习习，与回乡风情园相映，是张家川最美的草原秘境。","wiki":"关山","img":"images_gs/s294.svg"},
{"name":"庄浪朝那湫","label":"朝那湫天池","region":"甘肃省","city":"平凉市","county":"庄浪县","theme":"草原湿地","elev":2400,"best":"6-9月","lat":35.15,"lng":106.1,"desc":"关山深处的姊妹天池，前湫后湫碧水澄澈，传为上古帝王祭祀之地。池周草甸如茵、松林环绕，湖光山色宁静，是庄浪海拔最高的高山湖泊秘境。","wiki":"朝那湫","img":"images_gs/s295.svg"},
{"name":"迭部茨日那旧址","label":"茨日那毛主席旧居","region":"甘肃省","city":"甘南州","county":"迭部县","theme":"红色遗迹","elev":2400,"best":"全年","lat":34.15,"lng":103.3,"desc":"1935年毛泽东长征途经迭部时的旧居，在此下达夺取腊子口的作战命令。藏式木楼保存完好，与腊子口战役遗址相连，是长征路上的重要纪念地。","wiki":"茨日那","img":"images_gs/s296.svg"},
{"name":"永靖恐龙足迹","label":"刘家峡恐龙国家地质公园","region":"甘肃省","city":"临夏州","county":"永靖县","theme":"城市地标","elev":1700,"best":"全年","lat":35.85,"lng":103.25,"desc":"世界罕见的恐龙足印化石群，1.7亿年前恐龙足迹密集保存于岩层，规模居世界前列。博物馆与足迹化石现场相映，是永靖古生物文化的瑰宝。","wiki":"刘家峡恐龙","img":"images_gs/s297.svg"},
{"name":"碌曲郭莽湿地","label":"郭莽湿地","region":"甘肃省","city":"甘南州","county":"碌曲县","theme":"草原湿地","elev":3500,"best":"6-9月","lat":34.6,"lng":102.4,"desc":"尕海湿地延伸的高原草甸，河流蜿蜒、草滩如毯，黑颈鹤与斑头雁翔集。木栈道伸向湿地深处，登高可见河流九曲，是碌曲生态风光的代表性湿地。","wiki":"郭莽湿地","img":"images_gs/s298.svg"},
{"name":"文县白水江保护区","label":"白水江自然保护区","region":"甘肃省","city":"陇南市","county":"文县","theme":"森林山川","elev":2000,"best":"5-10月","lat":32.8,"lng":104.9,"desc":"大熊猫的重要栖息地，原始森林覆盖白水江流域，大熊猫、金丝猴与珙桐等珍稀物种繁衍生息。保护区山高林密、溪流纵横，是陇南生物多样性的宝库。","wiki":"白水江自然保护区","img":"images_gs/s299.svg"},
{"name":"灵台密须古城","label":"密须古城遗址","region":"甘肃省","city":"平凉市","county":"灵台县","theme":"古城遗址","elev":1200,"best":"全年","lat":35.08,"lng":107.58,"desc":"商代密须国都城遗址，诗经密人不恭的记载与古都遗存相印证。古城垣与青铜器出土地相映，是灵台先秦文明的重要遗址，被誉为商周历史之镜。","wiki":"密须国","img":"images_gs/s300.svg"},
{"name":"秦安凤山","label":"凤山古建筑群","region":"甘肃省","city":"天水市","county":"秦安县","theme":"古建寺院","elev":1400,"best":"全年","lat":34.86,"lng":105.67,"desc":"秦安县城东的明清古建筑群，泰山庙、文昌阁等庙宇依山层叠，飞檐翘角、气势恢宏，为陇上保存最完整的明清庙宇群之一。登凤山可瞰秦安全城与葫芦河。","wiki":"秦安凤山","img":"images_gs/s301.svg"},
{"name":"临夏红园","label":"红园","region":"甘肃省","city":"临夏州","county":"临夏市","theme":"古建寺院","elev":1900,"best":"全年","lat":35.6,"lng":103.21,"desc":"临夏市内的古典园林，亭台楼阁与砖雕木刻精美，集河州建筑艺术之大成。园中湖水曲桥、古树参天，是临夏人休闲怀古的历史名园。","wiki":"临夏红园","img":"images_gs/s302.svg"},
/* ---------- 补充：近年网红打卡地 ---------- */
{"name":"敦煌雅丹地质公园","label":"雅丹地质公园","region":"甘肃省","city":"酒泉市","county":"敦煌市","theme":"丹霞地貌","elev":900,"best":"全年（日落尤佳）","lat":40.45,"lng":93.55,"desc":"罗布泊边缘的雅丹魔鬼城，风蚀土丘如城堡舰队列阵戈壁，规模宏大，为世界地质公园。日落时金色雅丹与星空相映，是敦煌西线壮美终点。","wiki":"敦煌雅丹国家地质公园"},
{"name":"榆中青城古镇","label":"青城古镇","region":"甘肃省","city":"兰州市","county":"榆中县","theme":"古城遗址","elev":1500,"best":"全年","lat":36.45,"lng":104.35,"desc":"黄河岸边的千年古镇，古建筑群与梨园荷塘相映，有陇上江南之誉。近年因古镇风貌与黄河风情走红，是兰州近郊的古镇秘境。","wiki":"青城古镇"}
